import os
import subprocess

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
OUT = os.path.join(ROOT, "MAW_Manifest.txt")
RUNTIME_DIRS = ("Scripts/", "Data/", "ExeMods/")


def runtime(path):
    if path.startswith(RUNTIME_DIRS):
        return True
    return "/" not in path and path.lower().endswith((".dll", ".exe"))


def checked_for_extra(path):
    lower = path.lower()
    if lower.startswith("scripts/") and lower.endswith(".lua"):
        return True
    return lower.startswith("data/") and path.count("/") == 1 and lower.endswith(".lod")


def maw_files():
    out = subprocess.run(["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard"],
                         cwd=ROOT, capture_output=True, check=True).stdout.decode("utf-8")
    files = set()
    for path in out.split("\0"):
        if path and runtime(path) and os.path.isfile(os.path.join(ROOT, path)):
            files.add(path)
    return files


def base_files():
    files = set()
    with open(os.path.join(ROOT, ".gitignore"), encoding="utf-8-sig") as f:
        for line in f:
            path = line.strip()
            if not path or path.startswith(("#", "!")) or path.endswith("/"):
                continue
            if any(c in path for c in "*?["):
                continue
            path = path.lstrip("/")
            if checked_for_extra(path):
                files.add(path)
    return files


def main():
    maw = maw_files()
    base = base_files() - maw
    lines = ["# MAW file manifest, generated by .github/scripts/generate_manifest.py: do not edit by hand",
             "[maw]"]
    lines += sorted(maw, key=str.lower)
    lines.append("[base]")
    lines += sorted(base, key=str.lower)
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines) + "\n")
    print("MAW_Manifest.txt: %d MAW files, %d base files" % (len(maw), len(base)))


if __name__ == "__main__":
    main()
